const std = @import("std");

// Sorted (keysym, Unicode) little-endian u16 pairs for printable legacy keysyms.
// Generated by querying xkb_keysym_to_utf32 for 0x0100..0xfeff; no runtime library.
const legacy = @embedFile("assets/legacy-keysyms.bin");

pub fn codepoint(sym: u32) ?u21 {
    switch (sym) {
        32...126, 160...255 => return @intCast(sym),
        0x01000100...0x0100d7ff, 0x0100e000...0x0110ffff => return @intCast(sym - 0x01000000),
        0x100...0xfeff => {},
        else => return null,
    }
    var lo: usize = 0;
    var hi: usize = legacy.len / 4;
    while (lo < hi) {
        const mid = lo + (hi - lo) / 2;
        const entry = legacy[mid * 4 ..][0..4];
        const key = std.mem.readInt(u16, entry[0..2], .little);
        if (key == sym) return std.mem.readInt(u16, entry[2..4], .little);
        if (key < sym) lo = mid + 1 else hi = mid;
    }
    return null;
}

test "legacy and Unicode keysyms translate without treating function keys as text" {
    for ([_]u32{ 0x06c6, 0x07e1, 0x04b1, 0x0101f3b5 }, [_]u21{ 'ф', 'α', 'ア', '🎵' }) |key, character| {
        try std.testing.expectEqual(@as(?u21, character), codepoint(key));
    }
    try std.testing.expect(codepoint(0xff1b) == null);
}
